{
  "doneWhen": "All 6 parsnips are planted and watered on the open plot (x 7..9, y 3..5).",
  "modes": [
    {
      "macro": "skill",
      "params": { "name": "field-work" }
    }
  ],
  "skills": [
    {
      "name": "field-work",
      "skill": "async (b) => { const tiles = []; for (let y = 3; y <= 5; y++) { for (let x = 7; x <= 9; x++) { tiles.push([x, y]); } } for (const [x, y] of tiles) { b.log('Working tile ' + x + ',' + y); let r = await b.workTile(x, y, 0, 'ControllerX'); b.log('till: ' + JSON.stringify(r)); r = await b.workTile(x, y, 2, 'ControllerA'); b.log('plant: ' + JSON.stringify(r)); r = await b.workTile(x, y, 1, 'ControllerX'); b.log('water: ' + JSON.stringify(r)); } }",
      "check": "async (b) => { const obs = await b.observe(); return { ok: /parsnip/i.test(obs) && /water/i.test(obs), detail: obs.slice(0, 400) }; }"
    }
  ]
}
